/**
 * Model AdminUser
 * 
 */
export type AdminUser = $Result.DefaultSelection<Prisma.$AdminUserPayload>
/**
 * Model Upload
 * Every stored file (covers, story pages, product images, activity previews, music…).
 * Content tables reference files by `url`; this table is the inventory for auditing and cleanup.
 */
export type Upload = $Result.DefaultSelection<Prisma.$UploadPayload>
/**
 * Model AuditLog
 * Append-only staff accountability log (guide §23). Never updated or deleted.
 */
export type AuditLog = $Result.DefaultSelection<Prisma.$AuditLogPayload>
/**
 * Model DraftApproval
 * A proposed change awaiting Super Admin review (guide §2). `before` is the published
 * snapshot when the draft was made; approval is refused if the row has changed since.
 */
export type DraftApproval = $Result.DefaultSelection<Prisma.$DraftApprovalPayload>
/**
 * Model Setting
 * Small key/value settings, e.g. community.regularVisibleLimit, checklist.visibleLimit.
 */
export type Setting = $Result.DefaultSelection<Prisma.$SettingPayload>
/**
 * Model Country
 * One country list shared by subscriptions, shop and country access (guide §20).
 */
export type Country = $Result.DefaultSelection<Prisma.$CountryPayload>
/**
 * Model LearningRegion
 * "Regional learning category" (guide §5). Each has its own full learning catalogue.
 */
export type LearningRegion = $Result.DefaultSelection<Prisma.$LearningRegionPayload>
/**
 * Model CountryRestriction
 * Any enabled matching rule blocks access; a blocked section cannot be bypassed by an item (guide §21).
 */
export type CountryRestriction = $Result.DefaultSelection<Prisma.$CountryRestrictionPayload>
/**
 * Model ChildFieldSetting
 * Which child fields are collected, per region (Admin Panel Control Pointers §4), e.g. DOB.
 */
export type ChildFieldSetting = $Result.DefaultSelection<Prisma.$ChildFieldSettingPayload>
/**
 * Model Parent
 * A parent-app account (docs/PARENT_API.md). Kept apart from staff: own tokens, own routes (/api/app).
 */
export type Parent = $Result.DefaultSelection<Prisma.$ParentPayload>
/**
 * Model ParentSession
 * One signed-in device. The refresh token is `{id}.{secret}`; only the secret's hash is stored,
 * and it changes on every refresh. Revoked on sign-out, password change and account deletion.
 */
export type ParentSession = $Result.DefaultSelection<Prisma.$ParentSessionPayload>
/**
 * Model PasswordReset
 * "Forgot password": a 6-digit code by email, 15 minutes, 5 tries.
 */
export type PasswordReset = $Result.DefaultSelection<Prisma.$PasswordResetPayload>
/**
 * Model Child
 * Admins can read but never edit a child's personal details or earned scores (guide §4).
 */
export type Child = $Result.DefaultSelection<Prisma.$ChildPayload>
/**
 * Model ChildSubscription
 * Subscriptions are per child profile (guide §19).
 */
export type ChildSubscription = $Result.DefaultSelection<Prisma.$ChildSubscriptionPayload>
/**
 * Model DevelopmentArea
 * 
 */
export type DevelopmentArea = $Result.DefaultSelection<Prisma.$DevelopmentAreaPayload>
/**
 * Model ActivityCategory
 * Optional grouping inside an area; each has its own levels and activities.
 */
export type ActivityCategory = $Result.DefaultSelection<Prisma.$ActivityCategoryPayload>
/**
 * Model AgeGroup
 * Supported completed-year ages. No upper limit.
 */
export type AgeGroup = $Result.DefaultSelection<Prisma.$AgeGroupPayload>
/**
 * Model Level
 * Area level with unlock thresholds: BOTH score and mastered count must be met (guide §9).
 */
export type Level = $Result.DefaultSelection<Prisma.$LevelPayload>
/**
 * Model Question
 * Questionnaire MCQ. Difficulty and marks are admin-only — never shown to parents (guide §6).
 */
export type Question = $Result.DefaultSelection<Prisma.$QuestionPayload>
/**
 * Model QuestionOption
 * 
 */
export type QuestionOption = $Result.DefaultSelection<Prisma.$QuestionOptionPayload>
/**
 * Model Skill
 * 
 */
export type Skill = $Result.DefaultSelection<Prisma.$SkillPayload>
/**
 * Model SkillExpectation
 * Expected score for a skill at an age; below it → more recommendations (guide §10).
 */
export type SkillExpectation = $Result.DefaultSelection<Prisma.$SkillExpectationPayload>
/**
 * Model ActivityFamily
 * "Activity with its own difficulty levels" (Activity Flow §5). Level count is not capped.
 */
export type ActivityFamily = $Result.DefaultSelection<Prisma.$ActivityFamilyPayload>
/**
 * Model Activity
 * 
 */
export type Activity = $Result.DefaultSelection<Prisma.$ActivityPayload>
/**
 * Model ActivityStep
 * Guidance steps: optional, untimed, no marks.
 */
export type ActivityStep = $Result.DefaultSelection<Prisma.$ActivityStepPayload>
/**
 * Model ActivityPreview
 * 
 */
export type ActivityPreview = $Result.DefaultSelection<Prisma.$ActivityPreviewPayload>
/**
 * Model AssessmentConfig
 * Immutable snapshot of formulas, area weights, question weights, mandatory sets and required
 * counts. Saving rules creates a new revision; children keep the revision they started with.
 */
export type AssessmentConfig = $Result.DefaultSelection<Prisma.$AssessmentConfigPayload>
/**
 * Model MandatoryActivity
 * Working copy of the mandatory set (snapshotted into AssessmentConfig on save).
 */
export type MandatoryActivity = $Result.DefaultSelection<Prisma.$MandatoryActivityPayload>
/**
 * Model ProgressionSettings
 * Activity Flow §17 "Activity Progression Settings", one row per region.
 */
export type ProgressionSettings = $Result.DefaultSelection<Prisma.$ProgressionSettingsPayload>
/**
 * Model DevelopmentBase
 * Base 1 / 2 / 3 (Activity Flow §1, §10): assessment-% band → starting difficulty.
 */
export type DevelopmentBase = $Result.DefaultSelection<Prisma.$DevelopmentBasePayload>
/**
 * Model QuestionnaireSubmission
 * Re-evaluation replaces the current questionnaire score; it is never added (guide §7).
 */
export type QuestionnaireSubmission = $Result.DefaultSelection<Prisma.$QuestionnaireSubmissionPayload>
/**
 * Model ActivityAttempt
 * 
 */
export type ActivityAttempt = $Result.DefaultSelection<Prisma.$ActivityAttemptPayload>
/**
 * Model ActivityFeedback
 * 
 */
export type ActivityFeedback = $Result.DefaultSelection<Prisma.$ActivityFeedbackPayload>
/**
 * Model ChildAreaLevel
 * Earned level per area/category — monotonic: reassessment never demotes (guide §7).
 */
export type ChildAreaLevel = $Result.DefaultSelection<Prisma.$ChildAreaLevelPayload>
/**
 * Model ChildFamilyStage
 * Current difficulty per activity family (Activity Flow §19).
 */
export type ChildFamilyStage = $Result.DefaultSelection<Prisma.$ChildFamilyStagePayload>
/**
 * Model WeeklyAssignment
 * 
 */
export type WeeklyAssignment = $Result.DefaultSelection<Prisma.$WeeklyAssignmentPayload>
/**
 * Model LibraryCategory
 * Stories and rhymes keep separate category lists (guide §15).
 */
export type LibraryCategory = $Result.DefaultSelection<Prisma.$LibraryCategoryPayload>
/**
 * Model LibraryItem
 * A story (many chapters) or a rhyme (exactly one chapter — enforced in the service).
 */
export type LibraryItem = $Result.DefaultSelection<Prisma.$LibraryItemPayload>
/**
 * Model LibraryChapter
 * 
 */
export type LibraryChapter = $Result.DefaultSelection<Prisma.$LibraryChapterPayload>
/**
 * Model LibraryPage
 * 
 */
export type LibraryPage = $Result.DefaultSelection<Prisma.$LibraryPagePayload>
/**
 * Model LibraryPageImage
 * Stacked images on a page — no per-image description (guide §14).
 */
export type LibraryPageImage = $Result.DefaultSelection<Prisma.$LibraryPageImagePayload>
/**
 * Model ReadingHistory
 * Parent sees the last 5 chapters read.
 */
export type ReadingHistory = $Result.DefaultSelection<Prisma.$ReadingHistoryPayload>
/**
 * Model Favorite
 * 
 */
export type Favorite = $Result.DefaultSelection<Prisma.$FavoritePayload>
/**
 * Model LibraryEngagement
 * Recorded reading/listening engagement, used for notification audience filters (guide §18).
 */
export type LibraryEngagement = $Result.DefaultSelection<Prisma.$LibraryEngagementPayload>
/**
 * Model CommunityPost
 * 
 */
export type CommunityPost = $Result.DefaultSelection<Prisma.$CommunityPostPayload>
/**
 * Model Enquiry
 * 
 */
export type Enquiry = $Result.DefaultSelection<Prisma.$EnquiryPayload>
/**
 * Model EnquiryReply
 * 
 */
export type EnquiryReply = $Result.DefaultSelection<Prisma.$EnquiryReplyPayload>
/**
 * Model Notification
 * 
 */
export type Notification = $Result.DefaultSelection<Prisma.$NotificationPayload>
/**
 * Model Campaign
 * Group announcement. Filters combine with AND; one message per parent, not per child.
 */
export type Campaign = $Result.DefaultSelection<Prisma.$CampaignPayload>
/**
 * Model Plan
 * 
 */
export type Plan = $Result.DefaultSelection<Prisma.$PlanPayload>
/**
 * Model PlanPrice
 * Per-child monthly price. A missing row = not purchasable there; 0 = intentionally free.
 */
export type PlanPrice = $Result.DefaultSelection<Prisma.$PlanPricePayload>
/**
 * Model Product
 * 
 */
export type Product = $Result.DefaultSelection<Prisma.$ProductPayload>
/**
 * Model ProductImage
 * position 0 = cover.
 */
export type ProductImage = $Result.DefaultSelection<Prisma.$ProductImagePayload>
/**
 * Model ProductPrice
 * 
 */
export type ProductPrice = $Result.DefaultSelection<Prisma.$ProductPricePayload>
/**
 * Model Order
 * 
 */
export type Order = $Result.DefaultSelection<Prisma.$OrderPayload>
/**
 * Model OrderItem
 * Prices are snapshotted: changing the catalogue later never changes a paid order (guide §20).
 */
export type OrderItem = $Result.DefaultSelection<Prisma.$OrderItemPayload>
/**
 * Model AppContentEntry
 * Working draft of static parent-app text.
 */
export type AppContentEntry = $Result.DefaultSelection<Prisma.$AppContentEntryPayload>
/**
 * Model AppContentVersion
 * Immutable published snapshot. Parent sessions keep the version they started with.
 */
export type AppContentVersion = $Result.DefaultSelection<Prisma.$AppContentVersionPayload>
/**
 * Model ChecklistItem
 * Week 1, Week 2, and "later weeks" (week = 3) checklists (guide §22). Ticks award no points.
 */
export type ChecklistItem = $Result.DefaultSelection<Prisma.$ChecklistItemPayload>
/**
 * Model ChecklistTick
 * Per child — ticking for one child does not tick for a sibling.
 */
export type ChecklistTick = $Result.DefaultSelection<Prisma.$ChecklistTickPayload>

